def is_multiply_prime(a):
    """
    Returns True if the given number is the multiplication of 3 prime numbers, False otherwise.

    Parameters:
    a (int): The number to check. It is assumed to be less than 100.

    Returns:
    bool: Whether the number is the multiplication of 3 prime numbers.

    Examples:
    >>> is_multiply_prime(30)
    True
    30 = 2 * 3 * 5
    """
    # Function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Function to check if a number is the product of 3 prime numbers
    def is_product_of_three_primes(n):
        count = 0
        for i in range(2, n + 1):
            if n % i == 0 and is_prime(i):
                count += 1
                if count == 3:
                    return True
        return False

    return is_product_of_three_primes(a)
